const DSA_PATTERNS={
 sliding:{title:'Sliding window',recognize:'The problem asks about a contiguous subarray or substring and its length, sum, frequency, or longest/shortest valid range.',diagram:'Array:   [2] [1] [5] [1] [3] [2]\n           L ───── R\nWindow:   └────────┘\nMove R to grow; move L to restore the condition.',steps:['Identify what the current window stores (sum, counts, unique values).','Extend the right pointer one step at a time.','When the condition breaks, move the left pointer until it becomes valid.','Update the best answer at the correct moment.'],complexity:'Often O(n), because each pointer moves forward at most n times.'},
 pointers:{title:'Two pointers',recognize:'A sorted array, pair/triplet relationship, palindrome, partition, or a problem where two indices can move without revisiting work.',diagram:'Sorted: [1] [2] [4] [6] [9]\n         L →         ← R\nsum < target: move L right\nsum > target: move R left',steps:['Write down what each pointer represents.','Define the invariant: what do you know about the region already checked?','Move the pointer that can eliminate impossible candidates.','Check duplicate handling and boundary crossing.'],complexity:'Usually O(n) after any required sorting.'},
 hashing:{title:'Hash map / set',recognize:'Need fast membership, counts, duplicates, complements, frequency, or matching information seen earlier.',diagram:'Read x ──► compute key / complement\n                    │\n           seen? ───┴── no ──► store x\n             │ yes\n             ▼\n        answer found',steps:['Decide which fact must be remembered (value, count, index, state).','For pair-sum problems, check the complement before inserting the current value.','Explain what the map guarantees at each iteration.','Account for memory proportional to stored elements.'],complexity:'Average O(n) time and O(n) extra space for a single pass.'},
 binary:{title:'Binary search',recognize:'The data is sorted, or a yes/no feasibility condition is monotonic as a candidate answer increases or decreases.',diagram:'lo           mid           hi\n |-------------●-------------|\ntrue/false boundary is monotonic\nDiscard the half that cannot contain the answer.',steps:['State the search space and inclusive/exclusive boundaries.','Define a monotonic predicate or target comparison.','Prove each update keeps the answer inside the interval.','Check loop termination, off-by-one cases, and integer overflow.'],complexity:'O(log n) predicate checks, multiplied by predicate cost if non-constant.'},
 graph:{title:'BFS / DFS',recognize:'The input models connections, dependencies, reachability, components, shortest unweighted paths, or state transitions.',diagram:'       A\n      / \\\n     B   C       BFS: queue by layers\n    /     \\      DFS: follow a path deeply\n   D       E',steps:['Model nodes and edges; confirm directed versus undirected.','Track visited nodes so cycles do not loop forever.','Use BFS for shortest paths in unweighted graphs; DFS for reachability and components.','Include adjacency-list build cost and visited structure in complexity.'],complexity:'O(V + E) with adjacency lists.'},
 dp:{title:'Dynamic programming',recognize:'Overlapping subproblems with a reusable state; decisions reuse answers to smaller prefixes, suffixes, positions, or capacities.',diagram:'State i depends on smaller states\n dp[i] = best(dp[i-1], dp[i-2] + value[i])\n       ↙             ↘\n   subproblem      subproblem',steps:['Define exactly what dp[state] means in one sentence.','Write the recurrence from the available choices.','Set base cases and visit states in dependency order.','Count states times transitions; optimize memory only if safe.'],complexity:'Usually O(number of states × transitions per state).'}
};
function renderDsaPatternLab(){
 const active=state.selectedPattern||'sliding',p=DSA_PATTERNS[active]||DSA_PATTERNS.sliding;
 let html='<section class="panel pattern-lab"><div class="page-head"><div><div class="tiny-label">VISUAL DSA GUIDE</div><h2 class="panel-title">Read the problem. Spot the pattern.</h2><p class="panel-subtitle">Choose a pattern to see the mental model, recognition clues and solution workflow.</p></div><span class="badge">PATTERN LAB</span></div><div class="pattern-tabs">'+Object.keys(DSA_PATTERNS).map(k=>'<button type="button" class="pattern-tab '+(active===k?'active':'')+'" data-pattern-tab="'+k+'">'+esc(DSA_PATTERNS[k].title)+'</button>').join('')+'</div>';
 html+='<div class="pattern-detail"><div class="pattern-explainer"><div class="tiny-label">HOW TO RECOGNIZE IT</div><h3>'+esc(p.title)+'</h3><p>'+esc(p.recognize)+'</p><div class="pattern-complexity">'+esc(p.complexity)+'</div></div><pre class="dsa-diagram">'+esc(p.diagram)+'</pre></div><div class="pattern-steps"><h3>How to work through it</h3><ol>'+p.steps.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol></div>';
 html+='<div class="read-problem-grid"><div><h3>How to read any DSA question</h3><ol><li><b>Input and output:</b> What exactly must be returned?</li><li><b>Constraints:</b> Estimate which complexity is possible.</li><li><b>Brute force:</b> State the simplest correct approach first.</li><li><b>Structure:</b> Look for ranges, sorted data, membership, graph edges, or reusable states.</li><li><b>Invariant:</b> Explain why each step keeps the answer correct.</li><li><b>Tests:</b> Try minimum, duplicate, boundary, and extreme inputs.</li></ol></div><div><h3>Interview explanation checklist</h3><p>Before typing code, explain:</p><ul><li>Chosen pattern and why it fits.</li><li>Time complexity and auxiliary space.</li><li>What changes each iteration.</li><li>How you know the final result is correct.</li></ul><button class="btn btn-primary btn-sm" type="button" data-pane="compiler">Try in code editor ↗</button></div></div></section>';
 return html;
}
function compilerStarter(language){return COMPILER_STARTERS[language]||COMPILER_STARTERS.cpp;}
function renderCompilerResult(result){
 const data=result&&result.result?result.result:result||{},accepted=Number(data.statusId)===3;
 const badgeClass=accepted?'good':Number(data.statusId)>0?'warn':'';
 const meta=[data.timeSeconds!=null?'Time '+data.timeSeconds+' s':'',data.memoryKb!=null?'Memory '+Math.round(data.memoryKb/1024*100)/100+' MB':'',data.language||''].filter(Boolean).join(' · ');
 const sections=[['Program output',data.stdout],['Compilation output',data.compileOutput],['Standard error',data.stderr],['Runtime message',data.message]].filter(x=>x[1]);
 return '<div class="compiler-result-head"><div><span class="badge '+badgeClass+'">'+esc(data.status||'Completed')+'</span><h3>'+(accepted?'Run completed':Number(data.statusId)===4?'Wrong answer':'Run result')+'</h3></div><small>'+esc(meta)+'</small></div>'+(sections.length?sections.map(x=>'<section class="compiler-output-section"><b>'+esc(x[0])+'</b><pre>'+esc(x[1])+'</pre></section>').join(''):'<pre>(No output returned.)</pre>');
}
async function renderCompiler(){
 const lang=state.editorLanguage||'cpp',problem=state.editorProblem||null,code=state.editorCode!=null?state.editorCode:compilerStarter(lang);
 let html=pageHead('CODE PLAYGROUND · SANDBOXED COMPILER','Write. Run. Debug. Repeat.','A LeetCode-style practice workspace with stdin, expected output, compiler errors and runtime metrics. Code runs inside a sandbox with bounded CPU and memory.','<button type="button" class="btn btn-secondary" data-pane="dsa">Browse DSA problems ↗</button>');
 html+='<div class="compiler-notice"><span>⚙</span><div><b>Execution environment</b><p>Public Judge0 CE service · up to 3 seconds CPU, 5 seconds wall time and 128 MB memory per run. Do not paste credentials or sensitive code. Availability depends on the public service.</p></div></div>';
 html+='<div class="coding-workspace"><aside class="compiler-problem-panel"><div class="tiny-label">PROBLEM</div><h2>'+esc(problem&&problem.title||'Practice workspace')+'</h2><p>'+(problem?esc(problem.statement||'Open the official problem statement for full requirements and constraints.'):'Select a problem from DSA Practice, or use this space to test an algorithm or language syntax.')+'</p>'+(problem&&problem.practiceUrl?'<a class="link-quiet" target="_blank" rel="noopener noreferrer" href="'+esc(problem.practiceUrl)+'">View full statement ↗</a>':'<button class="btn btn-secondary btn-sm" type="button" data-pane="dsa">Choose a DSA problem</button>')+'<hr><h3>Before you run</h3><ol><li>Read constraints and examples.</li><li>Write the algorithm, then code it.</li><li>Provide custom input below.</li><li>Compare actual and expected output.</li><li>Record complexity in your DSA attempt.</li></ol><div class="compiler-tip"><b>Shortcut</b><p>Press Tab in the editor to indent. Ctrl/⌘ + Enter runs your code.</p></div></aside>';
 html+='<section class="compiler-main"><div class="compiler-toolbar"><label for="compilerLanguage">Language</label><select id="compilerLanguage">'+COMPILER_LANGUAGES.map(x=>'<option value="'+x.value+'" '+(lang===x.value?'selected':'')+'>'+esc(x.label)+'</option>').join('')+'</select><button type="button" class="btn btn-secondary btn-sm" id="compilerReset">Reset starter code</button><button type="button" class="btn btn-secondary btn-sm" id="compilerCopy">Copy code</button></div><div class="compiler-editor-shell"><div class="compiler-editor-title"><span><i></i><i></i><i></i></span><b>solution.'+({cpp:'cpp',c:'c',python:'py',java:'java',javascript:'js',typescript:'ts',go:'go',rust:'rs',csharp:'cs',ruby:'rb',php:'php',kotlin:'kt'}[lang]||'txt')+'</b><small>STDIN / STDOUT</small></div><textarea id="compilerSourceCode" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off" maxlength="24000" aria-label="Source code editor">'+esc(code)+'</textarea></div><div class="compiler-test-panels"><div class="field"><label for="compilerStdin">Custom input (stdin)</label><textarea id="compilerStdin" rows="5" maxlength="10000" placeholder="Example input">'+esc(state.editorStdin||'5\n1 2 3 4 5')+'</textarea></div><div class="field"><label for="compilerExpectedOutput">Expected output (optional)</label><textarea id="compilerExpectedOutput" rows="5" maxlength="10000" placeholder="Compare with this output">'+esc(state.editorExpectedOutput||'')+'</textarea></div></div><div class="compiler-runbar"><div><button type="button" class="btn btn-primary" id="compilerRun">▶ Run code</button><span id="compilerRunStatus" class="small-note">Ready</span></div><button type="button" class="btn btn-secondary btn-sm" id="compilerClearOutput">Clear output</button></div><div id="compilerResult" class="compiler-result" aria-live="polite"><div class="compiler-empty"><b>Your output will appear here.</b><p>Run the starter code or replace it with your solution. Errors and output show below.</p></div></div><p class="small-note">Editor supports 12 languages. Code is sent to the execution provider only when you click Run Code. Public APIs may impose fair-use limits.</p></section></div>';
 return html;
}
async function initCompilerEditor(root){
 const ta=root.querySelector('#compilerSourceCode');if(!ta)return;
 const addCss=(href)=>{if(!document.querySelector('link[data-compiler-css="'+href+'"]')){const l=document.createElement('link');l.rel='stylesheet';l.href=href;l.dataset.compilerCss=href;document.head.appendChild(l)}};
 const loadScript=(src)=>new Promise((resolve,reject)=>{if(document.querySelector('script[data-compiler-script="'+src+'"]'))return resolve();const s=document.createElement('script');s.src=src;s.async=true;s.dataset.compilerScript=src;s.onload=resolve;s.onerror=reject;document.head.appendChild(s)});
 try{
  addCss('https://cdnjs.cloudflare.com/ajax/libs/codemirror/5.65.16/codemirror.min.css');
  if(!window.CodeMirror)await loadScript('https://cdnjs.cloudflare.com/ajax/libs/codemirror/5.65.16/codemirror.min.js');
  const lang=state.editorLanguage||'cpp';
  const mode=({cpp:'text/x-c++src',c:'text/x-csrc',java:'text/x-java',python:'python',javascript:'javascript',typescript:'javascript',go:'text/x-go',rust:'text/x-rustsrc',csharp:'text/x-csharp',ruby:'ruby',php:'application/x-httpd-php',kotlin:'text/x-kotlin'}[lang]||'text/x-c++src');
  const modeFile=({cpp:'clike/clike',c:'clike/clike',java:'clike/clike',csharp:'clike/clike',kotlin:'clike/clike',python:'python/python',javascript:'javascript/javascript',typescript:'javascript/javascript',go:'go/go',rust:'rust/rust',ruby:'ruby/ruby',php:'php/php'}[lang]||'clike/clike');
  try{await loadScript('https://cdnjs.cloudflare.com/ajax/libs/codemirror/5.65.16/mode/'+modeFile+'.min.js')}catch(e){try{await loadScript('https://cdnjs.cloudflare.com/ajax/libs/codemirror/5.65.16/mode/'+modeFile+'.js')}catch(e2){}}
  if(root.querySelector('#compilerSourceCode')!==ta||state.codeMirror)return;
  if(document.documentElement.dataset.theme==='dark')addCss('https://cdnjs.cloudflare.com/ajax/libs/codemirror/5.65.16/theme/material-darker.min.css');
  state.codeMirror=window.CodeMirror.fromTextArea(ta,{mode,theme:document.documentElement.dataset.theme==='dark'?'material-darker':'default',lineNumbers:true,indentUnit:4,tabSize:4,indentWithTabs:false,lineWrapping:false,matchBrackets:true,viewportMargin:20,extraKeys:{'Ctrl-Enter':runCompiler,'Cmd-Enter':runCompiler,'Tab':'indentMore'}});
  state.codeMirror.setSize('100%',460);
  state.codeMirror.on('change',editor=>{state.editorCode=editor.getValue()});
 }catch(e){const note=root.querySelector('.compiler-editor-title small');if(note)note.textContent='Plain text fallback · editor library unavailable'}
}

async function renderJobs(){const d=await api('/applications');state.applications=d.applications||[];const statuses=['interested','preparing','applied','recruiter_screening','assessment','technical_interview','hiring_manager','final_round','offer','accepted','rejected','withdrawn'];let html=pageHead('CAREER EXECUTION','Keep every application moving.','Track companies, stages, interviews and follow-ups. Application records are private to your account.','<button class="btn btn-primary" id="jumpAddApplication">＋ Add application</button>');html+='<div class="stat-grid">'+statCard('Applications',Number(d.stats?.total||0),'All saved records')+statCard('Active pipeline',Number(d.stats?.active||0),'Not closed or withdrawn')+statCard('Offers',Number(d.stats?.offers||0),'Offer or accepted status')+statCard('Follow-ups due',state.applications.filter(a=>a.next_follow_up_at&&new Date(a.next_follow_up_at)<=new Date()).length,'Based on saved follow-up dates')+'</div><section class="panel" id="addApplicationPanel"><h2 class="panel-title">Add a job application</h2><p class="panel-subtitle">CareerOS does not fetch live listings in this release—add applications from a source you trust.</p><form id="applicationForm" class="form-grid">'+field('Company','appCompany','Company name','text',{required:true,max:160})+field('Job title','appTitle','Position title','text',{required:true,max:180})+field('Application URL (optional)','appUrl','https://careers.example.com/role','url',{max:600})+field('Location','appLocation','City / remote','text',{max:160})+field('Minimum salary (INR, optional)','appSalaryMin','Numeric amount','number',{max:15})+field('Maximum salary (INR, optional)','appSalaryMax','Numeric amount','number',{max:15})+field('Stage','appStatus','','select',{value:'interested',options:statuses.map(s=>({value:s,label:s.replaceAll('_',' ')}))})+field('Application date','appDate','','date')+field('Next follow-up (optional)','appFollowUp','','date')+field('Resume version used','appResumeVersion','e.g. Backend v3','text',{max:100})+field('Recruiter/contact (optional)','appRecruiter','Contact details or note','text',{max:240})+field('Notes','appNotes','Interview notes, requirements or next step','textarea',{wide:true,max:3000})+'<div class="span-2"><button type="submit" class="btn btn-primary">Save application</button><p class="form-message" id="applicationMsg"></p></div></form></section><section class="panel" style="margin-top:15px"><h2 class="panel-title">Your application pipeline</h2><p class="panel-subtitle">Change the stage or delete a record. Follow-up dates and notes stay editable.</p>';if(!state.applications.length)html+=emptyState('No job applications yet','Add a role you are interested in and keep its next action visible.');else{html+='<div class="application-board">';const columns=[['Interested','interested','preparing'],['In progress','applied','recruiter_screening','assessment','technical_interview'],['Final stages','hiring_manager','final_round','offer'],['Closed','accepted','rejected','withdrawn']];html+=columns.map(col=>'<div class="app-column"><h3>'+col[0]+' · '+state.applications.filter(a=>col.slice(1).includes(a.status)).length+'</h3>'+state.applications.filter(a=>col.slice(1).includes(a.status)).map(a=>'<div class="app-ticket"><b>'+esc(a.job_title)+'</b><small>'+esc(a.company)+' · '+esc(a.location||'Location not set')+'</small><small>'+(a.next_follow_up_at?'Follow up: '+esc(dateText(a.next_follow_up_at)):'No follow-up date')+'</small><select data-app-status="'+a.id+'" aria-label="Application status for '+esc(a.company)+'">'+statuses.map(s=>'<option value="'+s+'" '+(a.status===s?'selected':'')+'>'+s.replaceAll('_',' ')+'</option>').join('')+'</select><div class="form-actions"><button class="btn btn-secondary btn-sm" data-app-save="'+a.id+'">Save stage</button><button class="btn btn-secondary btn-sm" data-app-delete="'+a.id+'">Delete</button></div></div>').join('')+'</div>').join('')+'</div>'}html+='</section>';return html}
async function renderOpportunities(){
 const f=state.opportunityFilters||{q:'',location:'',stage:'any'};
 let html=pageHead('LIVE JOB DISCOVERY','Find real opportunities.','Listings are fetched from live third-party job feeds. Open the publisher’s page to confirm eligibility and apply.','<button class="btn btn-secondary" id="refreshOpportunities">↻ Refresh feed</button>');
 html+='<section class="panel"><form id="opportunitySearchForm" class="form-grid"><div class="field"><label for="opportunityQuery">Role, skill or company</label><input id="opportunityQuery" maxlength="100" placeholder="e.g. backend engineer, product, design" value="'+esc(f.q||'')+'"></div><div class="field"><label for="opportunityLocation">Location or remote</label><input id="opportunityLocation" maxlength="100" placeholder="e.g. India, Ahmedabad, remote" value="'+esc(f.location||'')+'"></div><div class="field"><label for="opportunityStage">Best fit</label><select id="opportunityStage"><option value="any" '+(f.stage==='any'?'selected':'')+'>All career stages</option><option value="student" '+(f.stage==='student'?'selected':'')+'>Student / early career</option><option value="professional" '+(f.stage==='professional'?'selected':'')+'>Working professional</option><option value="entrepreneur" '+(f.stage==='entrepreneur'?'selected':'')+'>Freelance / startup / growth</option></select></div><div class="field" style="align-self:end"><button class="btn btn-primary" type="submit">Search live jobs ↗</button></div></form><p class="small-note">Sources: Himalayas, Jobicy and Remotive public feeds. Feeds may focus on remote roles; no listing is guaranteed to remain open.</p></section>';
 html+='<section id="opportunityResults" class="panel" style="margin-top:15px"><div class="loading-block large"></div></section>';
 const params=new URLSearchParams({limit:'60',stage:f.stage||'any'});
 if(f.q)params.set('q',f.q);if(f.location)params.set('location',f.location);
 try{
  const d=await api('/jobs?'+params.toString());
  state.opportunities=d.jobs||[];
  const el=$('#opportunityResults');
  if(!el)return html;
  const sourceHtml=(d.sources||[]).map(s=>'<span class="badge '+(s.status==='live'?'good':'warn')+'">'+esc(s.name)+': '+esc(s.status)+(s.count!=null?' · '+Number(s.count):'')+'</span>').join(' ');
  let body='<div class="page-head"><div><div class="tiny-label">LIVE FEED · '+Number(d.total||0)+' MATCHES</div><h2 class="panel-title">Current listings</h2><p class="panel-subtitle">Fetched '+esc(d.fetchedAt?new Date(d.fetchedAt).toLocaleString():'just now')+'</p></div><div class="page-actions">'+sourceHtml+'</div></div>';
  if(d.error)body+='<div class="notice"><span>!</span><div>'+esc(d.error)+'</div></div>';
  else if(!state.opportunities.length)body+=emptyState('No live listings match these filters','Change your search terms or location. No placeholder jobs are inserted.');
  else body+='<div class="topic-grid">'+state.opportunities.map((j,i)=>'<article class="topic-card"><div class="topic-top"><span>'+esc(j.source||'External source')+'</span><span class="badge">'+esc(j.employmentType||'Role')+'</span></div><h3>'+esc(j.title)+'</h3><p><b>'+esc(j.company)+'</b> · '+esc(j.location||'Location not stated')+'</p><p>'+esc(j.description||'The publisher has not supplied a summary.')+'</p><div class="topic-top"><span>'+esc(j.salary||'Salary not provided')+'</span><span>'+esc(j.seniority||'Seniority not stated')+'</span></div><small class="small-note">'+(j.publishedAt?'Published '+esc(dateText(j.publishedAt)):'Publication date not provided')+'</small><div class="form-actions"><a class="btn btn-primary btn-sm" target="_blank" rel="noopener noreferrer" href="'+esc(j.applyUrl||j.jobUrl||j.sourceUrl)+'">View & apply ↗</a><button class="btn btn-secondary btn-sm" data-track-job="'+i+'">Track this role</button></div></article>').join('')+'</div>';
  body+='<p class="small-note">'+esc(d.disclaimer||'Listings come from third-party sources. Confirm details before applying.')+'</p>';
  el.innerHTML=body;
 }catch(e){
  state.opportunities=[];
  const el=$('#opportunityResults');
  if(el)el.innerHTML='<div class="notice"><span>!</span><div>'+esc(e.message||'Live job feeds are unavailable right now. Retry later; no dummy listings are shown.')+'</div></div>';
 }
 return html;
}
function planSection(title, items){
 if(!Array.isArray(items)||!items.length)return '';
 return '<section style="margin-top:14px"><h3>'+esc(title)+'</h3><ul class="result-list">'+items.map(x=>'<li>'+esc(typeof x==='string'?x:x&&typeof x==='object'?Object.entries(x).map(([k,v])=>k.replaceAll(/([A-Z])/g,' $1')+': '+(Array.isArray(v)?v.join(', '):String(v??''))).join(' — '):String(x??''))+'</li>').join('')+'</ul></section>';
}
